  issues: { message: string; path: PropertyKey[] }[],
): { code: string; message: string; field?: string }[] {
  return issues.map((issue) => ({
    code: 'INVALID_FIELD',
    message: issue.message,
    ...(issue.path.length > 0 ? { field: issue.path.join('.') } : {}),
  }));
}

