              id: '42',
              displayName: 'Contributor',
              role: 'submitter',
              approvalState: 'approved',
              requestedCompetition: { competitionId: '7', name: 'Premier T20' },
              competitionScopes: [{ competitionId: '7', name: 'Premier T20' }],
