    expect(
      administratorSubmitterAccessUpdateSchema.safeParse({
        approved: true,
        competitionIds: ['7'],
      }).success,
    ).toBe(true);
  });

  test('does not allow revoked access to retain competition scopes', () => {
    expect(
      administratorSubmitterAccessUpdateSchema.safeParse({
        approved: false,
        competitionIds: ['7'],
      }).success,
