import { beforeEach, describe, expect, it, vi } from 'vitest';

const { createClientMock, deleteUserMock } = vi.hoisted(() => ({
  createClientMock: vi.fn(),
  deleteUserMock: vi.fn(),
}));

vi.mock('@supabase/supabase-js', () => ({
  createClient: createClientMock,
