import { Router } from 'express';

import type { VerifyAccessToken } from '../../auth/supabase-auth';
import { requireAuthentication } from '../../middleware/require-authentication';
import { requireAdministrator } from '../../middleware/require-authorization';
import type { SynchronizeAccount } from '../accounts/account.service';
import {
  createAdminListUsersController,
  createAdminRejectSubmitterAccessRequestController,
  createAdminUpdateSubmitterAccessController,
} from './admin.controller';
import type { AdminService } from './admin.service';

export function createAdminRouter(
  verifyAccessToken: VerifyAccessToken,
  synchronizeAccount: SynchronizeAccount,
  service: AdminService,
): Router {
  const router = Router();
  const authenticate = requireAuthentication(verifyAccessToken, synchronizeAccount);
  const authorize = requireAdministrator();

  router.get('/admin/users', authenticate, authorize, createAdminListUsersController(service));
  router.patch(
    '/admin/users/:userId/submitter-access',
    authenticate,
    authorize,
    createAdminUpdateSubmitterAccessController(service),
  );
  router.post(
    '/admin/users/:userId/submitter-access/rejection',
    authenticate,
    authorize,
    createAdminRejectSubmitterAccessRequestController(service),
  );

  return router;
}

import {
  administratorSubmitterAccessResponseSchema,
  administratorSubmitterAccessUpdateSchema,
  administratorUserManagementResponseSchema,
} from '@sport-analytics/contracts';
import type { RequestHandler, Response } from 'express';

import type { ApplicationAccount } from '../accounts/account';
import {
  AdminManagementConflictError,
  AdminEmailLookupUnavailableError,
  AdminUserNotFoundError,
  InvalidCompetitionScopesError,
} from './admin.errors';
import type { AdminService } from './admin.service';

function getAuthenticatedAccount(response: Response): ApplicationAccount {
  const account = response.locals.authenticatedAccount as ApplicationAccount | undefined;

  if (!account) {
    throw new Error('Administrator controller requires an authenticated application account');
  }

  return account;
}

function validationDetails(
  issues: { message: string; path: PropertyKey[] }[],
): { code: string; message: string; field?: string }[] {
  return issues.map((issue) => ({
    code: 'INVALID_FIELD',
    message: issue.message,
    ...(issue.path.length > 0 ? { field: issue.path.join('.') } : {}),
  }));
}

function isDatabaseIdentifier(value: string): boolean {
  if (!/^\d+$/.test(value)) {
    return false;
  }

  try {
    return BigInt(value) <= 9_223_372_036_854_775_807n;
  } catch {
    return false;
  }
}

