export function createAdminUpdateRoleController(service: AdminService): RequestHandler {
  return (request, response, next) => {
    const targetAccountId = request.params.userId;
    const parsed = administratorRoleUpdateSchema.safeParse(request.body);

    if (!targetAccountId || !isDatabaseIdentifier(targetAccountId) || !parsed.success) {
      response.status(422).json({
        error: {
          code: 'VALIDATION_FAILED',
          message: 'The role update is invalid.',
          details: !targetAccountId || !isDatabaseIdentifier(targetAccountId)
            ? [{ code: 'INVALID_FIELD', field: 'userId', message: 'The user identifier is invalid.' }]
            : validationDetails(parsed.error.issues),
        },
      });
      return;
    }

    let administrator: ApplicationAccount;
    try {
      administrator = getAuthenticatedAccount(response);
    } catch (error) {
      next(error);
      return;
    }

    void service
      .updateRole(administrator, targetAccountId, parsed.data)
      .then((result) => response.status(200).json(administratorSubmitterAccessResponseSchema.parse(result)))
      .catch((error: unknown) => {
        if (error instanceof AdminUserNotFoundError) {
          response.status(404).json({ error: { code: 'USER_NOT_FOUND', message: error.message } });
          return;
        }
        if (error instanceof AdminManagementConflictError) {
          response.status(409).json({ error: { code: error.code, message: error.message } });
          return;
        }
        if (error instanceof AdminEmailLookupUnavailableError) {
          response.status(503).json({
            error: { code: 'ADMIN_EMAIL_LOOKUP_UNAVAILABLE', message: error.message },
          });
          return;
        }
        next(error);
      });
  };
}

export function createAdminUpdateSubmitterAccessController(service: AdminService): RequestHandler {
  return (request, response, next) => {
    const targetAccountId = request.params.userId;

    if (!targetAccountId || !isDatabaseIdentifier(targetAccountId)) {
      response.status(422).json({
        error: {
          code: 'VALIDATION_FAILED',
          message: 'The submitter access update is invalid.',
    },

    async rejectSubmitterAccessRequest(targetAccountId, administratorAccountId) {
      return applySubmitterAccessTransition(
        pool,
        targetAccountId,
        administratorAccountId,
        'reject',
        [],
      );
    },
    async updateRole(targetAccountId, administratorAccountId, update) {
      return withTransaction(pool, async (client) => {
        const targetResult = await executeQuery<TargetAccountRow>(
          client,
          `
            SELECT application_role AS role, submitter_approval_state AS "approvalState",
              submitter_requested_competition_id::text AS "requestedCompetitionId", disabled_at AS "disabledAt"
            FROM app_user WHERE app_user_id = $1 FOR UPDATE
          `,
          [targetAccountId],
        );
        const target = targetResult.rows[0];
        if (!target) throw new AdminUserNotFoundError();
